  List<int> result = [];

  int depth = 0;

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      depth++;
    } else if (parenString[i] == ')') {
      depth--;
      while (depth != 0 && parenString.substring(i - depth + 1, i).contains('(')) {
        depth--;
