String sortNumbers(String numbers) {
  List<String> list = numbers.split(" ");

  // Sort the list in ascending order using bubble sort.
  for (int i = 0; i < list.length - 1; i++) {
    for (int j = 0; j < list.length - 1 - i; j++) {
      if (list[j].compareTo(list[j + 1]) > 0) {
        String temp = list[j];
        list[j] = list[j + 1];
        list[j + 1] = temp;
      }
    }
  }

  // Join the sorted list back into a single string and return it.
  return list.join(' ');
}

