String circularShift(int x, int shift) {
  String s = x.toString();

  if (shift == 0 || x < 10) return s;

  int numDigits = s.length;
  int effectiveShift = shift % numDigits;

  List<String> digits = [];
  for (int i = 0; i < numDigits; i++) {
    digits.add(s[i]);
  }

  digits.removeRange(0, effectiveShift);
  digits.addAll(digits.sublist(effectiveShift));

  return digits.join('');
}

