String antiShuffle(String s) {
  if (s.isEmpty) return '';

  List<String> words = s.split(' ');
  String result = "";

  for (int i = 0; i < words.length; i++) {
    // Reverse each word and append it to the result string.
    String reversedWord = words[i].split('').reversed.join();

    // Append a space between words, except after the last word.
    if (i != words.length - 1) {
      result += "$reversedWord ";
    } else {
      result += reversedWord;
    }
  }

  return result.trim(); 
}

