String _swapCase(String str) {
  final result = StringBuffer();
  for (int i = 0; i < str.length; i++) {
    final char = str[i];
    if (char == char.toUpperCase()) {
      result.write(char.toLowerCase());
    } else {
      result.write(char.toUpperCase());
    }
  }
  return result.toString();
}

