int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  final cols = grid[0].length;

  List<bool> visited = List.generate(rows * cols, (index) => false);
  int filledCells = 0;

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (!visited[i * cols + j] && grid[i][j] == 1) {
        List<int> queue = [i * cols + j];
        List<int> directions = [-cols - 1, -cols, -cols + 1, -1, 1, cols - 1, cols, cols + 1];

        while (queue.isNotEmpty) {
          int currentPos = queue.removeAt(0);
          int row = currentPos ~/ cols;
          int col = currentPos % cols;

          visited[currentPos] = true;
          filledCells++;

          for (int direction in directions) {
            int newRow = row + (direction ~/ cols);
            int newCol = col + (direction % cols);

            if (newRow >= 0 && newRow < rows && 
                newCol >= 0 && newCol < cols && 
                !visited[newRow * cols + newCol] && 
                grid[newRow][newCol] == 1) {
              visited[newRow * cols + newCol] = true;

              if (filledCells <= capacity) {
                continue;
              } else {
                break;
              }
            }
          }

          if (filledCells > capacity) {
            break;
          }

          // Add the neighbors to the end of the queue
          for (int direction in directions) {
            int newRow = row + (direction ~/ cols);
            int newCol = col + (direction % cols);

            if (newRow >= 0 && newRow < rows && 
                newCol >= 0 && newCol < cols && 
                !visited[newRow * cols + newCol] && 
                grid[newRow][newCol] == 1) {
              queue.add(newRow * cols + newCol);
            }
          }
        }
      }
    }

    if (filledCells > capacity) {
      break;
    }
