      result.add(1);
    } else if (i % 2 == 0) {
      // Even row: find the minimum value in the current column.
      var minVal = grid[0][i];
      for (var j = 1; j < grid.length; j++) {
        if (grid[j][i] < minVal) {
          minVal = grid[j][i];
        }
      }
      result.add(minVal);
    } else {
      // Odd row: find the maximum value in the current column.
      var maxVal = grid[0][i];
      for (var j = 1; j < grid.length; j++) {
        if (grid[j][i] > maxVal) {
          maxVal = grid[j][i];
        }
      }
      result.add(maxVal);
    }
  }

  return result.take(k).toList();
}

