List<String> sortedListSum(List<String> lst) {
  List<String> sortedLst = List.from(lst);
  sortedLst.sort();

  List<String> newLst = [];
  for (String i in sortedLst) {
    if (i.length % 2 == 0) {
      newLst.add(i);
    }
  }

  newLst.sort((a, b) {
    int lengthComparison = a.length.compareTo(b.length);
    if (lengthComparison != 0) {
      return lengthComparison;
    }
    return a.compareTo(b);
  });

  return newLst;
}

