import 'dart:math';

@pragma('vm:entry-point')
List<int> generateIntegers(int a, int b) {
  int lower = max(2, min(a, b));
  int upper = min(8, max(a, b));

  List<int> result = [];
  for (int i = lower; i <= upper; i++) {
    if (i % 2 == 0) {
      result.add(i);
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(generateIntegers(2, 8));  // [2, 4, 6, 8]
  print(generateIntegers(8, 2));  // [2, 4, 6, 8]
  print(generateIntegers(10, 14)); // []
  print(generateIntegers(2, 2));  // [2]
  print(generateIntegers(1, 9));  // [2, 4, 6, 8]
  print(generateIntegers(5, 7));  // [6]
}

